void GIFS::EndPrim(int fEOP)
{
    if (m_pqwPrim)
    {
        uint c = m_cregAll / m_creg;
        if ((uint)m_pb & 0xF)
        {
            ulong *pul = (ulong *)m_pb;
            m_pb = (uchar *)(pul + 1);
            *pul = 0;
        }
        QW *pqw = m_pqwPrim;
        uint x;
        if (fEOP) x = pqw->aun[0] | 0x8000; else x = pqw->aun[0];
        pqw->aun[0] = x | c;
        m_pqwPrim = NULL;
    }
}

